arguments.content:
/* Grepo application styles v1.0
   Design direction: gecko identity, lemon/lime accents, marble-white surfaces.
   Tokens imported from design/tokens.css.
*/
@import './design/tokens.css';

/* ── Reset ──────────────────────────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  min-height: 100vh;
  background: var(--grepo-canvas);
  color: var(--grepo-ink);
  font-family: var(--grepo-font-sans);
  font-size: 15px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

button, a, input, select, textarea {
  font: inherit;
}

button {
  cursor: pointer;
}

a {
  color: inherit;
  text-decoration: none;
}

/* ── App shell ──────────────────────────────────────────────────────────── */
.grepo-app {
  display: flex;
  min-height: 100vh;
  flex-direction: column;
}

/* ── Topbar ─────────────────────────────────────────────────────────────── */
.topbar {
  position: sticky;
  top: 0;
  z-index: 100;
  display: grid;
  height: var(--grepo-topbar-h);
  grid-template-columns: var(--grepo-nav-w) minmax(0,1fr) auto;
  align-items: center;
  gap: var(--grepo-space-4);
  padding: 0 var(--grepo-space-4);
  border-bottom: 1px solid var(--grepo-line);
  background: var(--grepo-surface);
  box-shadow: var(--grepo-shadow-card);
}

.topbar__brand {
  display: flex;
  align-items: center;
  gap: var(--grepo-space-2);
  text-decoration: none;
  color: var(--grepo-ink);
  font-weight: 700;
  font-size: 15px;
}

.topbar__logo {
  height: 32px;
  width: auto;
  object-fit: contain;
}

.topbar__wordmark {
  font-size: 16px;
  font-weight: 800;
  letter-spacing: -0.3px;
}

.topbar__project {
  display: flex;
  align-items: center;
  gap: var(--grepo-space-2);
  min-width: 0;
  overflow: hidden;
}

.topbar__project-name {
  font-size: 13px;
  font-weight: 700;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.topbar__badge {
  flex: none;
  padding: 3px var(--grepo-space-2);
  border: 1px solid var(--grepo-line);
  border-radius: 6px;
  color: var(--grepo-text-secondary);
  font-family: var(--grepo-font-mono);
  font-size: 10px;
  text-transform: uppercase;
}

.topbar__badge--revision {
  background: var(--grepo-surface-muted);
}

.topbar__actions {
  display: flex;
  align-items: center;
  gap: var(--grepo-space-2);
}

/* ── Workspace layout ───────────────────────────────────────────────────── */
.workspace-layout {
  display: grid;
  flex: 1;
  grid-template-columns: var(--grepo-nav-w) var(--grepo-tree-w) minmax(0,1fr) var(--grepo-panel-w);
  grid-template-rows: 1fr;
  min-height: calc(100vh - var(--grepo-topbar-h));
}

.workspace-layout--no-panel {
  grid-template-columns: var(--grepo-nav-w) var(--grepo-tree-w) minmax(0,1fr);
}

.workspace-layout--no-tree {
  grid-template-columns: var(--grepo-nav-w) minmax(0,1fr);
}

/* ── Nav rail ───────────────────────────────────────────────────────────── */
.nav-rail {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: var(--grepo-space-4) 0;
  border-right: 1px solid var(--grepo-line);
  background: var(--grepo-surface);
  overflow-y: auto;
}

.nav-item {
  display: flex;
  align-items: center;
  gap: var(--grepo-space-2);
  padding: var(--grepo-space-2) var(--grepo-space-4);
  margin: 0 var(--grepo-space-2);
  border: 0;
  border-radius: var(--grepo-space-2);
  background: transparent;
  color: var(--grepo-text-secondary);
  font-size: 13px;
  font-weight: 500;
  text-decoration: none;
  transition: background var(--grepo-duration-fast), color var(--grepo-duration-fast);
  cursor: pointer;
  text-align: left;
}

.nav-item:hover {
  background: var(--grepo-surface-muted);
  color: var(--grepo-ink);
}

.nav-item--active {
  background: var(--grepo-lime);
  color: var(--grepo-ink);
  font-weight: 700;
}

.nav-item:focus-visible {
  outline: 2px solid var(--grepo-focus);
  outline-offset: 2px;
}

.nav-item__icon {
  width: 18px;
  height: 18px;
  flex: none;
  opacity: 0.7;
}

.nav-item--active .nav-item__icon {
  opacity: 1;
}

.nav-group-label {
  padding: var(--grepo-space-4) var(--grepo-space-6) var(--grepo-space-1);
  color: var(--grepo-text-secondary);
  font-family: var(--grepo-font-mono);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.nav-divider {
  height: 1px;
  margin: var(--grepo-space-2) var(--grepo-space-4);
  background: var(--grepo-line);
}

/* ── File tree panel ────────────────────────────────────────────────────── */
.tree-panel {
  display: flex;
  flex-direction: column;
  border-right: 1px solid var(--grepo-line);
  background: var(--grepo-surface);
  overflow: hidden;
}

.tree-panel__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--grepo-space-4) var(--grepo-space-3);
  border-bottom: 1px solid var(--grepo-line);
  flex: none;
}

.tree-panel__title {
  margin: 0;
  font-size: 12px;
  font-weight: 700;
  color: var(--grepo-text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.tree-panel__count {
  font-family: var(--grepo-font-mono);
  font-size: 10px;
  color: var(--grepo-text-secondary);
}

.tree-panel__search {
  padding: var(--grepo-space-2) var(--grepo-space-3);
  border-bottom: 1px solid var(--grepo-line);
  flex: none;
}

.tree-search-input {
  display: block;
  width: 100%;
  padding: var(--grepo-space-2) var(--grepo-space-3);
  border: 1px solid var(--grepo-line);
  border-radius: var(--grepo-space-2);
  background: var(--grepo-surface-muted);
  color: var(--grepo-ink);
  font-size: 12px;
  transition: border-color var(--grepo-duration-fast);
}

.tree-search-input:focus {
  outline: none;
  border-color: var(--grepo-green-strong);
  background: var(--grepo-surface);
}

.tree-panel__scroll {
  flex: 1;
  overflow-y: auto;
  overflow-x: hidden;
  padding: var(--grepo-space-2) 0;
}

/* ── Tree nodes ─────────────────────────────────────────────────────────── */
.tree-node {
  display: flex;
  align-items: center;
  gap: 4px;
  min-height: 28px;
  padding: 0 var(--grepo-space-2);
  border: 0;
  background: transparent;
  color: var(--grepo-ink);
  font-size: 12px;
  cursor: pointer;
  width: 100%;
  text-align: left;
  user-select: none;
  transition: background var(--grepo-duration-fast);
}

.tree-node:hover {
  background: var(--grepo-surface-muted);
}

.tree-node--selected {
  background: rgba(198, 248, 74, 0.25);
  font-weight: 600;
}

.tree-node--selected:hover {
  background: rgba(198, 248, 74, 0.35);
}

.tree-node:focus-visible {
  outline: 2px solid var(--grepo-focus);
  outline-offset: -2px;
}

.tree-node__indent {
  flex: none;
  display: inline-block;
}

.tree-node__chevron {
  flex: none;
  width: 14px;
  height: 14px;
  color: var(--grepo-text-secondary);
  transition: transform var(--grepo-duration-fast);
}

.tree-node__chevron--open {
  transform: rotate(90deg);
}

.tree-node__chevron--leaf {
  opacity: 0;
  pointer-events: none;
}

.tree-node__icon {
  flex: none;
  width: 14px;
  height: 14px;
  margin-right: 2px;
}

.tree-node__label {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tree-node__lang {
  flex: none;
  color: var(--grepo-text-secondary);
  font-family: var(--grepo-font-mono);
  font-size: 9px;
  text-transform: uppercase;
  margin-left: auto;
  padding-right: var(--grepo-space-2);
}

/* Tree empty/loading */
.tree-message {
  padding: var(--grepo-space-4) var(--grepo-space-3);
  color: var(--grepo-text-secondary);
  font-size: 12px;
}

/* ── Content area ───────────────────────────────────────────────────────── */
.content-area {
  display: flex;
  flex-direction: column;
  min-width: 0;
  background: var(--grepo-canvas);
  overflow: hidden;
}

.content-header {
  padding: var(--grepo-space-6) var(--grepo-space-8) var(--grepo-space-4);
  border-bottom: 1px solid var(--grepo-line);
  flex: none;
}

.content-header__eyebrow {
  margin: 0 0 var(--grepo-space-1);
  color: var(--grepo-text-secondary);
  font-family: var(--grepo-font-mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.content-header__title {
  margin: 0;
  font-size: 22px;
  font-weight: 700;
  line-height: 1.25;
  color: var(--grepo-ink);
}

.content-scroll {
  flex: 1;
  overflow: auto;
  padding: var(--grepo-space-6) var(--grepo-space-8);
}

/* ── Right contextual panel ─────────────────────────────────────────────── */
.context-panel {
  display: flex;
  flex-direction: column;
  border-left: 1px solid var(--grepo-line);
  background: var(--grepo-surface);
  overflow: hidden;
}

.context-panel__header {
  padding: var(--grepo-space-4) var(--grepo-space-4);
  border-bottom: 1px solid var(--grepo-line);
  flex: none;
}

.context-panel__title {
  margin: 0;
  font-size: 12px;
  font-weight: 700;
  color: var(--grepo-text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.context-panel__scroll {
  flex: 1;
  overflow-y: auto;
  padding: var(--grepo-space-4);
}

/* ── Cards ──────────────────────────────────────────────────────────────── */
.card {
  background: var(--grepo-surface);
  border: 1px solid var(--grepo-line);
  border-radius: var(--grepo-radius-card);
  box-shadow: var(--grepo-shadow-card);
  padding: var(--grepo-space-6);
}

.card + .card {
  margin-top: var(--grepo-space-4);
}

/* ── Stat grid ──────────────────────────────────────────────────────────── */
.stat-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: var(--grepo-space-3);
  margin: 0;
  padding: 0;
  list-style: none;
}

.stat-card {
  padding: var(--grepo-space-4) var(--grepo-space-4);
  background: var(--grepo-surface);
  border: 1px solid var(--grepo-line);
  border-radius: var(--grepo-radius-control);
}

.stat-card__label {
  display: block;
  margin-bottom: var(--grepo-space-1);
  color: var(--grepo-text-secondary);
  font-family: var(--grepo-font-mono);
  font-size: 9px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.stat-card__value {
  display: block;
  font-size: 22px;
  font-weight: 700;
  color: var(--grepo-ink);
  line-height: 1.1;
}

.stat-card__sub {
  display: block;
  margin-top: var(--grepo-space-1);
  color: var(--grepo-text-secondary);
  font-size: 11px;
}

/* ── Buttons ────────────────────────────────────────────────────────────── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: var(--grepo-space-2);
  min-height: 40px;
  padding: 0 var(--grepo-space-4);
  border: 0;
  border-radius: var(--grepo-radius-control);
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  transition: opacity var(--grepo-duration-fast), background var(--grepo-duration-fast);
  text-decoration: none;
}

.btn:focus-visible {
  outline: 2px solid var(--grepo-focus);
  outline-offset: 2px;
}

.btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.btn--primary {
  background: var(--grepo-lime);
  color: var(--grepo-ink);
}

.btn--primary:hover:not(:disabled) {
  background: #b8f030;
}

.btn--secondary {
  background: var(--grepo-surface-muted);
  color: var(--grepo-ink);
  border: 1px solid var(--grepo-line);
}

.btn--secondary:hover:not(:disabled) {
  background: var(--grepo-line);
}

.btn--ghost {
  background: transparent;
  color: var(--grepo-text-secondary);
  border: 1px solid var(--grepo-line);
}

.btn--ghost:hover:not(:disabled) {
  background: var(--grepo-surface-muted);
  color: var(--grepo-ink);
}

.btn--sm {
  min-height: 32px;
  padding: 0 var(--grepo-space-3);
  font-size: 12px;
}

/* ── Form elements ──────────────────────────────────────────────────────── */
.form-input {
  display: block;
  width: 100%;
  padding: var(--grepo-space-3) var(--grepo-space-4);
  border: 1px solid var(--grepo-line);
  border-radius: var(--grepo-radius-control);
  background: var(--grepo-surface);
  color: var(--grepo-ink);
  font-size: 14px;
  transition: border-color var(--grepo-duration-fast);
}

.form-input:focus {
  outline: none;
  border-color: var(--grepo-green-strong);
  box-shadow: 0 0 0 3px rgba(40, 100, 58, 0.12);
}

.form-input::placeholder {
  color: var(--grepo-text-secondary);
}

.form-label {
  display: block;
  margin-bottom: var(--grepo-space-2);
  font-size: 12px;
  font-weight: 600;
  color: var(--grepo-ink);
}

/* ── Status / alert banners ─────────────────────────────────────────────── */
.alert {
  display: flex;
  gap: var(--grepo-space-3);
  padding: var(--grepo-space-3) var(--grepo-space-4);
  border-radius: var(--grepo-radius-control);
  font-size: 13px;
}

.alert--error {
  background: rgba(163, 50, 50, 0.08);
  border-left: 3px solid var(--grepo-error);
  color: #7a2020;
}

.alert--warning {
  background: rgba(122, 82, 0, 0.08);
  border-left: 3px solid var(--grepo-caution);
  color: var(--grepo-caution);
}

.alert--info {
  background: var(--grepo-surface-muted);
  border-left: 3px solid var(--grepo-line);
  color: var(--grepo-text-secondary);
}

/* ── Loading skeletons ──────────────────────────────────────────────────── */
@keyframes skeleton-pulse {
  0%, 100% { opacity: 0.5; }
  50%       { opacity: 1;   }
}

.skeleton {
  background: var(--grepo-line);
  border-radius: var(--grepo-space-1);
  animation: skeleton-pulse 1.4s ease-in-out infinite;
}

.skeleton--text {
  height: 14px;
  margin-bottom: var(--grepo-space-2);
}

.skeleton--text:last-child {
  width: 60%;
}

/* ── Empty states ───────────────────────────────────────────────────────── */
.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--grepo-space-4);
  min-height: 40vh;
  text-align: center;
  color: var(--grepo-text-secondary);
}

.empty-state__icon {
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  border: 1px solid var(--grepo-line);
  border-radius: var(--grepo-space-3);
  background: rgba(198, 248, 74, 0.15);
  font-size: 20px;
}

.empty-state__title {
  margin: 0;
  font-size: 17px;
  font-weight: 600;
  color: var(--grepo-ink);
}

.empty-state__body {
  margin: 0;
  font-size: 13px;
  max-width: 360px;
  line-height: 1.6;
}

/* ── Integration slots ──────────────────────────────────────────────────── */
.slot-placeholder {
