.coverage-bar {
  display: flex;
  gap: var(--grepo-space-6);
  padding: var(--grepo-space-4) 0;
  flex-wrap: wrap;
}

.coverage-bar__item {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.coverage-bar__label {
  font-family: var(--grepo-font-mono);
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--grepo-text-secondary);
}

.coverage-bar__value {
  font-size: 18px;
  font-weight: 700;
  color: var(--grepo-ink);
}

/* ── Table ──────────────────────────────────────────────────────────────── */
.data-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
}

.data-table th {
  position: sticky;
  top: 0;
  background: var(--grepo-surface);
  padding: var(--grepo-space-2) var(--grepo-space-3);
  text-align: left;
  font-family: var(--grepo-font-mono);
  font-size: 9px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--grepo-text-secondary);
  border-bottom: 1px solid var(--grepo-line);
}

.data-table td {
  padding: var(--grepo-space-2) var(--grepo-space-3);
  border-bottom: 1px solid var(--grepo-line);
  color: var(--grepo-text-secondary);
  vertical-align: middle;
}

.data-table tr:hover td {
  background: var(--grepo-surface-muted);
}

.data-table__path {
  color: var(--grepo-ink);
  font-family: var(--grepo-font-mono);
  font-size: 11px;
  cursor: pointer;
  background: none;
  border: none;
  padding: 0;
  text-align: left;
}

.data-table__path:hover {
  text-decoration: underline;
  text-underline-offset: 3px;
}

/* ── Responsive ─────────────────────────────────────────────────────────── */
@media (max-width: 1200px) {
  :root {
    --grepo-panel-w: 0px;
  }
  .workspace-layout {
    grid-template-columns: var(--grepo-nav-w) var(--grepo-tree-w) minmax(0,1fr);
  }
  .context-panel {
    display: none;
  }
}

@media (max-width: 900px) {
  :root {
    --grepo-tree-w: 220px;
  }
}

@media (max-width: 700px) {
  .topbar {
    grid-template-columns: auto minmax(0,1fr);
  }
  .workspace-layout {
    display: flex;
    flex-direction: column;
  }
  .nav-rail {
    display: flex;
    flex-direction: row;
    overflow-x: auto;
    border-right: 0;
    border-bottom: 1px solid var(--grepo-line);
    padding: var(--grepo-space-2) var(--grepo-space-2);
  }
  .nav-group-label, .nav-divider {
    display: none;
  }
  .tree-panel {
    max-height: 220px;
    border-right: 0;
    border-bottom: 1px solid var(--grepo-line);
  }
  .import-steps {
    grid-template-columns: 1fr;
  }
  .import-form__row {
    flex-direction: column;
  }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

