}

.btn--secondary {
  background: var(--grepo-surface-muted);
  color: var(--grepo-ink);
  border: 1px solid var(--grepo-line);
}

.btn--secondary:hover:not(:disabled) {
  background: var(--grepo-line);
}

.btn--ghost {
  background: transparent;
  color: var(--grepo-text-secondary);
  border: 1px solid var(--grepo-line);
}

.btn--ghost:hover:not(:disabled) {
  background: var(--grepo-surface-muted);
  color: var(--grepo-ink);
}

.btn--sm {
  min-height: 32px;
  padding: 0 var(--grepo-space-3);
  font-size: 12px;
}

/* ── Form elements ──────────────────────────────────────────────────────── */
.form-input {
  display: block;
  width: 100%;
  padding: var(--grepo-space-3) var(--grepo-space-4);
  border: 1px solid var(--grepo-line);
  border-radius: var(--grepo-radius-control);
  background: var(--grepo-surface);
  color: var(--grepo-ink);
  font-size: 14px;
  transition: border-color var(--grepo-duration-fast);
}

.form-input:focus {
  outline: none;
  border-color: var(--grepo-green-strong);
  box-shadow: 0 0 0 3px rgba(40, 100, 58, 0.12);
}

.form-input::placeholder {
  color: var(--grepo-text-secondary);
}

.form-label {
  display: block;
  margin-bottom: var(--grepo-space-2);
  font-size: 12px;
  font-weight: 600;
  color: var(--grepo-ink);
}

/* ── Status / alert banners ─────────────────────────────────────────────── */
.alert {
  display: flex;
  gap: var(--grepo-space-3);
  padding: var(--grepo-space-3) var(--grepo-space-4);
  border-radius: var(--grepo-radius-control);
  font-size: 13px;
}

.alert--error {
  background: rgba(163, 50, 50, 0.08);
  border-left: 3px solid var(--grepo-error);
  color: #7a2020;
}

.alert--warning {
  background: rgba(122, 82, 0, 0.08);
  border-left: 3px solid var(--grepo-caution);
  color: var(--grepo-caution);
}

.alert--info {
  background: var(--grepo-surface-muted);
  border-left: 3px solid var(--grepo-line);
  color: var(--grepo-text-secondary);
}

/* ── Loading skeletons ──────────────────────────────────────────────────── */
@keyframes skeleton-pulse {
  0%, 100% { opacity: 0.5; }
  50%       { opacity: 1;   }
}

.skeleton {
  background: var(--grepo-line);
  border-radius: var(--grepo-space-1);
  animation: skeleton-pulse 1.4s ease-in-out infinite;
}

.skeleton--text {
  height: 14px;
  margin-bottom: var(--grepo-space-2);
}

.skeleton--text:last-child {
  width: 60%;
}

/* ── Empty states ───────────────────────────────────────────────────────── */
.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--grepo-space-4);
  min-height: 40vh;
  text-align: center;
  color: var(--grepo-text-secondary);
}

.empty-state__icon {
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  border: 1px solid var(--grepo-line);
  border-radius: var(--grepo-space-3);
  background: rgba(198, 248, 74, 0.15);
  font-size: 20px;
}

.empty-state__title {
  margin: 0;
  font-size: 17px;
  font-weight: 600;
  color: var(--grepo-ink);
}

.empty-state__body {
  margin: 0;
  font-size: 13px;
  max-width: 360px;
  line-height: 1.6;
}

/* ── Integration slots ──────────────────────────────────────────────────── */
.slot-placeholder {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: var(--grepo-space-4);
  padding: var(--grepo-space-8);
  background: var(--grepo-surface-muted);
  border: 1px dashed var(--grepo-line);
  border-radius: var(--grepo-radius-card);
}

.slot-placeholder__badge {
  display: inline-block;
  padding: 3px var(--grepo-space-2);
  background: var(--grepo-surface);
  border: 1px solid var(--grepo-line);
  border-radius: 6px;
  color: var(--grepo-text-secondary);
  font-family: var(--grepo-font-mono);
  font-size: 9px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.slot-placeholder__title {
  margin: 0;
  font-size: 16px;
  font-weight: 700;
  color: var(--grepo-ink);
}

.slot-placeholder__description {
  margin: 0;
  font-size: 13px;
  color: var(--grepo-text-secondary);
  line-height: 1.6;
  max-width: 520px;
}

.slot-placeholder__dev {
  margin-top: var(--grepo-space-2);
  padding: var(--grepo-space-4);
  background: var(--grepo-surface);
  border: 1px solid var(--grepo-line);
  border-radius: var(--grepo-space-3);
  width: 100%;
}

.slot-placeholder__dev-title {
  margin: 0 0 var(--grepo-space-2);
  font-family: var(--grepo-font-mono);
  font-size: 10px;
  color: var(--grepo-text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.slot-placeholder__code {
  display: block;
  font-family: var(--grepo-font-mono);
  font-size: 11px;
  color: var(--grepo-ink);
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

/* ── Source viewer ──────────────────────────────────────────────────────── */
.source-viewer {
  display: flex;
  flex-direction: column;
  height: 100%;
  background: var(--grepo-surface);
  border: 1px solid var(--grepo-line);
  border-radius: var(--grepo-radius-card);
  overflow: hidden;
}

.source-viewer__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--grepo-space-4);
  padding: var(--grepo-space-3) var(--grepo-space-4);
  border-bottom: 1px solid var(--grepo-line);
  background: var(--grepo-surface-muted);
  flex: none;
}

.source-viewer__path {
  font-family: var(--grepo-font-mono);
  font-size: 11px;
  color: var(--grepo-ink);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.source-viewer__meta {
  display: flex;
  gap: var(--grepo-space-2);
  flex: none;
}

.source-badge {
  padding: 2px var(--grepo-space-2);
  border-radius: 4px;
  background: var(--grepo-surface);
  border: 1px solid var(--grepo-line);
  color: var(--grepo-text-secondary);
  font-family: var(--grepo-font-mono);
  font-size: 9px;
  text-transform: uppercase;
}

.source-viewer__code {
  flex: 1;
  overflow: auto;
  padding: var(--grepo-space-4) 0;
}

.source-table {
  width: 100%;
  border-collapse: collapse;
  font-family: var(--grepo-font-mono);
  font-size: 12px;
  line-height: 1.5;
}

.source-table td {
  padding: 0;
  vertical-align: top;
}

.source-table__num {
  padding: 0 var(--grepo-space-3) 0 var(--grepo-space-4);
  color: var(--grepo-text-secondary);
  text-align: right;
  user-select: none;
  min-width: 40px;
  font-size: 11px;
  white-space: nowrap;
}

.source-table__line {
  padding: 0 var(--grepo-space-4) 0 var(--grepo-space-2);
  white-space: pre;
  overflow: visible;
  color: var(--grepo-ink);
}

.source-table tr:hover .source-table__line {
  background: var(--grepo-surface-muted);
}

.source-table tr:hover .source-table__num {
  background: var(--grepo-surface-muted);
}

.source-viewer__truncation {
  padding: var(--grepo-space-3) var(--grepo-space-6);
  border-top: 1px solid var(--grepo-line);
  background: var(--grepo-surface-muted);
  color: var(--grepo-text-secondary);
  font-size: 12px;
  flex: none;
  text-align: center;
}

/* ── Map canvas ─────────────────────────────────────────────────────────── */
.map-canvas {
  display: flex;
  flex-direction: column;
  height: 100%;
  background: var(--grepo-canvas);
}

.map-toolbar {
  display: flex;
  align-items: center;
  gap: var(--grepo-space-2);
  padding: var(--grepo-space-3) var(--grepo-space-4);
  border-bottom: 1px solid var(--grepo-line);
  background: var(--grepo-surface);
  flex: none;
  flex-wrap: wrap;
}

.map-toolbar__spacer {
  flex: 1;
}

.map-svg-container {
  flex: 1;
  position: relative;
  overflow: hidden;
  cursor: grab;
}

.map-svg-container:active {
  cursor: grabbing;
}

.map-svg {
  width: 100%;
  height: 100%;
}

/* SVG node styles */
.map-node rect {
  fill: var(--grepo-surface);
  stroke: var(--grepo-line);
  stroke-width: 1;
  rx: 8;
}

.map-node--directory rect {
  fill: var(--grepo-surface-muted);
}

.map-node--repository rect {
  fill: var(--grepo-lime);
  stroke: #a0d020;
  stroke-width: 2;
}

.map-node--selected rect {
  stroke: var(--grepo-green-strong);
  stroke-width: 2;
}

.map-node text {
  font-family: var(--grepo-font-sans);
  font-size: 11px;
  fill: var(--grepo-ink);
  pointer-events: none;
}

.map-edge {
  stroke: var(--grepo-line);
  stroke-width: 1;
  fill: none;
}

/* ── Import page ────────────────────────────────────────────────────────── */
.import-page {
  min-height: 100vh;
  background: var(--grepo-canvas);
  display: flex;
  flex-direction: column;
}

.import-hero {
  max-width: 760px;
  margin: 0 auto;
  padding: 80px var(--grepo-space-6) 64px;
  text-align: center;
}

.import-hero__logo {
  height: 56px;
  margin: 0 auto var(--grepo-space-6);
  display: block;
  object-fit: contain;
}

.import-hero__tagline {
  margin: 0 0 var(--grepo-space-8);
  font-size: clamp(30px, 5vw, 46px);
  font-weight: 700;
  line-height: 1.1;
  color: var(--grepo-ink);
}

.import-hero__sub {
  margin: 0 0 var(--grepo-space-8);
  font-size: 16px;
  color: var(--grepo-text-secondary);
  line-height: 1.7;
}

.import-steps {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--grepo-space-4);
  margin: 0 auto var(--grepo-space-8);
  max-width: 660px;
  padding: 0;
  list-style: none;
}

.import-step {
  padding: var(--grepo-space-4);
  background: var(--grepo-surface);
  border: 1px solid var(--grepo-line);
  border-radius: var(--grepo-radius-card);
  text-align: center;
}

.import-step__num {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  background: var(--grepo-lime);
  border-radius: 50%;
  font-size: 13px;
  font-weight: 700;
  color: var(--grepo-ink);
  margin-bottom: var(--grepo-space-2);
}

.import-step__label {
  font-size: 13px;
  font-weight: 600;
  color: var(--grepo-ink);
}

.import-card {
  max-width: 660px;
  margin: 0 auto;
  padding: var(--grepo-space-8);
  background: var(--grepo-surface);
  border: 1px solid var(--grepo-line);
  border-radius: var(--grepo-radius-card);
  box-shadow: var(--grepo-shadow-card);
}

.import-card__tabs {
  display: flex;
  gap: 0;
  border-bottom: 1px solid var(--grepo-line);
  margin-bottom: var(--grepo-space-6);
}

.import-tab {
  padding: var(--grepo-space-2) var(--grepo-space-6);
  border: 0;
  border-bottom: 2px solid transparent;
  background: transparent;
  color: var(--grepo-text-secondary);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  margin-bottom: -1px;
  transition: color var(--grepo-duration-fast), border-color var(--grepo-duration-fast);
}

.import-tab--active {
  color: var(--grepo-ink);
  border-bottom-color: var(--grepo-lime);
}

.import-form {
  display: flex;
  flex-direction: column;
  gap: var(--grepo-space-4);
}

.import-form__row {
  display: flex;
  gap: var(--grepo-space-3);
  align-items: flex-end;
}

.import-form__field {
  flex: 1;
  min-width: 0;
}

.import-policy-notice {
  font-size: 11px;
  color: var(--grepo-text-secondary);
  line-height: 1.5;
  border-top: 1px solid var(--grepo-line);
  padding-top: var(--grepo-space-4);
  margin-top: var(--grepo-space-2);
}

.import-progress {
  margin-top: var(--grepo-space-6);
  padding: var(--grepo-space-6);
  background: var(--grepo-surface-muted);
  border: 1px solid var(--grepo-line);
  border-radius: var(--grepo-radius-card);
}

.import-progress__label {
  font-size: 13px;
  font-weight: 600;
  color: var(--grepo-ink);
  margin-bottom: var(--grepo-space-3);
}

.import-progress__stage {
  display: flex;
  align-items: center;
  gap: var(--grepo-space-2);
  font-size: 12px;
  color: var(--grepo-text-secondary);
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

.spinner {
  width: 14px;
  height: 14px;
  border: 2px solid var(--grepo-line);
  border-top-color: var(--grepo-green-strong);
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
  flex: none;
}

/* ── Recent imports ─────────────────────────────────────────────────────── */
.recent-list {
  max-width: 660px;
  margin: var(--grepo-space-6) auto 0;
}

.recent-list__heading {
  font-family: var(--grepo-font-mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--grepo-text-secondary);
  margin-bottom: var(--grepo-space-2);
}

.recent-item {
  display: flex;
  align-items: center;
  gap: var(--grepo-space-3);
  padding: var(--grepo-space-3) var(--grepo-space-4);
  background: var(--grepo-surface);
  border: 1px solid var(--grepo-line);
  border-radius: var(--grepo-radius-control);
  cursor: pointer;
  transition: background var(--grepo-duration-fast);
  margin-bottom: var(--grepo-space-2);
  text-align: left;
  width: 100%;
  border-color: var(--grepo-line);
}

.recent-item:hover {
  background: var(--grepo-surface-muted);
}

.recent-item__name {
  flex: 1;
  font-size: 13px;
  font-weight: 600;
  color: var(--grepo-ink);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.recent-item__meta {
  flex: none;
  font-family: var(--grepo-font-mono);
  font-size: 10px;
  color: var(--grepo-text-secondary);
}

/* ── Capability chip ────────────────────────────────────────────────────── */
.cap-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px var(--grepo-space-2);
  border-radius: 6px;
  font-family: var(--grepo-font-mono);
  font-size: 9px;
  font-weight: 600;
  text-transform: uppercase;
}

.cap-chip--full {
  background: rgba(40,100,58,0.12);
  color: var(--grepo-green-strong);
}

.cap-chip--text {
  background: var(--grepo-surface-muted);
  color: var(--grepo-text-secondary);
  border: 1px solid var(--grepo-line);
}

.cap-chip--binary {
  background: rgba(122,82,0,0.08);
  color: var(--grepo-caution);
}

/* ── Coverage summary ───────────────────────────────────────────────────── */
.coverage-bar {
  display: flex;
  gap: var(--grepo-space-6);
  padding: var(--grepo-space-4) 0;
  flex-wrap: wrap;
}

.coverage-bar__item {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.coverage-bar__label {
  font-family: var(--grepo-font-mono);
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--grepo-text-secondary);
}

.coverage-bar__value {
  font-size: 18px;
  font-weight: 700;
  color: var(--grepo-ink);
}

/* ── Table ──────────────────────────────────────────────────────────────── */
.data-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
}

.data-table th {
  position: sticky;
  top: 0;
  background: var(--grepo-surface);
  padding: var(--grepo-space-2) var(--grepo-space-3);
  text-align: left;
  font-family: var(--grepo-font-mono);
  font-size: 9px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--grepo-text-secondary);
  border-bottom: 1px solid var(--grepo-line);
}

.data-table td {
  padding: var(--grepo-space-2) var(--grepo-space-3);
  border-bottom: 1px solid var(--grepo-line);
  color: var(--grepo-text-secondary);
  vertical-align: middle;
}

.data-table tr:hover td {
  background: var(--grepo-surface-muted);
}

.data-table__path {
  color: var(--grepo-ink);
  font-family: var(--grepo-font-mono);
  font-size: 11px;
  cursor: pointer;
  background: none;
  border: none;
  padding: 0;
  text-align: left;
}

.data-table__path:hover {
  text-decoration: underline;
  text-underline-offset: 3px;
}

/* ── Responsive ─────────────────────────────────────────────────────────── */
@media (max-width: 1200px) {
  :root {
    --grepo-panel-w: 0px;
  }
  .workspace-layout {
    grid-template-columns: var(--grepo-nav-w) var(--grepo-tree-w) minmax(0,1fr);
  }
  .context-panel {
    display: none;
  }
}

@media (max-width: 900px) {
  :root {
    --grepo-tree-w: 220px;
  }
}

@media (max-width: 700px) {
  .topbar {
    grid-template-columns: auto minmax(0,1fr);
  }
  .workspace-layout {
    display: flex;
    flex-direction: column;
  }
  .nav-rail {
    display: flex;
    flex-direction: row;
    overflow-x: auto;
    border-right: 0;
    border-bottom: 1px solid var(--grepo-line);
    padding: var(--grepo-space-2) var(--grepo-space-2);
  }
  .nav-group-label, .nav-divider {
    display: none;
  }
  .tree-panel {
    max-height: 220px;
    border-right: 0;
    border-bottom: 1px solid var(--grepo-line);
  }
  .import-steps {
    grid-template-columns: 1fr;
  }
  .import-form__row {
    flex-direction: column;
  }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

